def run(c:list[str])->None:print('+',' '.join(c));subprocess.run(c,check=True)
def extract(root:Path)->None:
 with zipfile.ZipFile(io.BytesIO(base64.b85decode(''.join(DATA.split())))) as z:
  if set(z.namelist())!=set(FILES):raise RuntimeError('Manifest mismatch')
  for n in FILES:
   p=PurePosixPath(n)
   if p.is_absolute() or '..' in p.parts:raise RuntimeError(f'Unsafe path {n}')
   t=root.joinpath(*p.parts);t.parent.mkdir(parents=True,exist_ok=True);t.write_bytes(z.read(n));print('created ',n)
def main()->int:
 a=argparse.ArgumentParser(description='Generate Kachmohol 2099 Version 11 / 1.1');a.add_argument('--clean',action='store_true');a.add_argument('--build',action='store_true');o=a.parse_args();r=Path.cwd()
 if o.clean:
  for n in FILES+EXTRAS:
   p=r/n
   if p.is_file():p.unlink()
  for n in ('src','docs','public'):
   p=r/n
   if p.exists():shutil.rmtree(p)
 extract(r);print('\nKachmohol 2099 Version 11 / 1.1 generated.')
 if o.build:
  if not shutil.which('npm'):print('npm not found',file=sys.stderr);return 2
  run(['npm','install']);run(['npm','run','build']);print('\nBuild successful.')
 else:print('Next: npm install && npm run build')
 print('Commit and push to main to deploy.');return 0
if __name__=='__main__':raise SystemExit(main())
